module.exports = async (args) => {
  const fs = require('fs').promises;
  const file = args.inputFileObj;
  const streams = file.ffProbeData?.streams || [];
  const videos = streams.filter(s => s.codec_type === 'video');
  const video = videos[0];
  const done = (number, reason) => {
    args.jobLog(reason);
    return { outputFileObj: file, outputNumber: number, variables: args.variables };
  };
  // Conservative first deployment: MKV, one progressive SDR H.264 video.
  if (!/\.mkv$/i.test(file._id) || videos.length !== 1 || video.codec_name !== 'h264') {
    return done(2, 'Skip: only single-video H.264 MKV files are eligible.');
  }
  if (video.width > 1920 || video.height > 1080
      || !['bt709', 'smpte170m', 'bt470bg'].includes(video.color_transfer)
      || !['progressive', 'unknown', undefined].includes(video.field_order)
      || /dovi|dolby|hdr|smpte2084|arib-std-b67/i.test(JSON.stringify(video.side_data_list || []))
      || /hdr|dolby vision/i.test(JSON.stringify(file.mediaInfo?.track?.map(t => t.HDR_Format) || []))) {
    return done(2, 'Skip: HDR, unknown transfer, interlaced, or above 1080p.');
  }
  const stat = await fs.stat(file._id);
  const pilot = file._id.startsWith('/pilot/');
  if (stat.nlink > 1 || (!pilot && Date.now() - stat.mtimeMs < 86400000)) {
    return done(2, 'Skip: hardlinked or modified in the last 24 hours.');
  }
  for (const folder of [require('path').dirname(file._id), '/temp']) {
    const space = await fs.statfs(folder);
    if (space.bavail * space.bsize < 500 * 1024 ** 3 + stat.size * 2) {
      throw new Error('Insufficient headroom: preserve 500 GiB plus twice the source size.');
    }
  }
  args.variables.sourceSnapshot = { size: stat.size, mtimeMs: stat.mtimeMs };
  return done(1, 'Eligible SDR H.264 source; original retained until all checks pass.');
};

module.exports = async (args) => {
  const command = args.variables.ffmpegCommand;
  if (!command?.init) throw new Error('FFmpeg command was not initialized');
  command.shouldProcess = true;
  command.container = 'mkv';
  command.hardwareDecoding = false;
  command.overallInputArguments.push('-init_hw_device', 'qsv=hw:/dev/dri/renderD128');
  command.overallOuputArguments.push('-map_metadata', '0', '-map_chapters', '0');
  for (const stream of command.streams) {
    stream.outputArgs = stream.codec_type === 'video'
      ? ['-c:{outputIndex}', 'hevc_qsv', '-global_quality', '22', '-preset', 'slow',
        '-profile:v', 'main10', '-pix_fmt', 'p010le']
      : ['-c:{outputIndex}', 'copy'];
  }
  return { outputFileObj: args.inputFileObj, outputNumber: 1, variables: args.variables };
};

module.exports = async (args) => {
  const { spawn } = require('child_process');
  // Decode every video/audio track and make even recoverable decode errors fatal.
  await new Promise((resolve, reject) => {
    const child = spawn(args.ffmpegPath, ['-nostdin', '-v', 'error', '-xerror',
      '-err_detect', 'explode', '-i', args.inputFileObj._id,
      '-map', '0:v', '-map', '0:a?', '-f', 'null', '-'], { shell: false });
    let errors = '';
    child.stdout.resume();
    child.stderr.on('data', chunk => { errors = (errors + chunk.toString()).slice(-8000); });
    child.on('error', reject);
    child.on('close', code => {
      if (code !== 0 || errors.trim()) reject(new Error(`Decode check failed (${code}): ${errors}`));
      else resolve();
    });
  });
  args.jobLog('Strict full video/audio decode passed.');
  return { outputFileObj: args.inputFileObj, outputNumber: 1, variables: args.variables };
};

module.exports = async (args) => {
  const fs = require('fs').promises;
  const before = args.originalLibraryFile;
  const after = args.inputFileObj;
  const snapshot = args.variables.sourceSnapshot;
  const stat = await fs.stat(before._id);
  if (!snapshot || stat.size !== snapshot.size || stat.mtimeMs !== snapshot.mtimeMs) {
    throw new Error('Source changed during encoding; keep original.');
  }
  const a = before.ffProbeData?.streams || [];
  const b = after.ffProbeData?.streams || [];
  if (a.length !== b.length) throw new Error('Stream count changed; keep original.');
  for (let i = 0; i < a.length; i++) {
    if (a[i].codec_type !== b[i].codec_type) throw new Error('Stream type changed');
    if (a[i].codec_type === 'video') {
      if (b[i].codec_name !== 'hevc' || !/10/.test(b[i].pix_fmt || '')
          || a[i].width !== b[i].width || a[i].height !== b[i].height) {
        throw new Error('Unexpected video format or dimensions; keep original.');
      }
    } else if (a[i].codec_name !== b[i].codec_name
        || a[i].channels !== b[i].channels
        || a[i].tags?.language !== b[i].tags?.language) {
      throw new Error('Audio/subtitle/attachment mismatch; keep original.');
    }
    for (const flag of ['default', 'forced']) {
      if ((a[i].disposition?.[flag] || 0) !== (b[i].disposition?.[flag] || 0)) {
        throw new Error('Track disposition changed; keep original.');
      }
    }
  }
  return { outputFileObj: after, outputNumber: 1, variables: args.variables };
};
